var t=`0187-chicken-cacciatore`;var n=`world-0187`;var a=`IT`;var r=`southern-europe`;var s=4;var o=76;var l={en:`Chicken Cacciatore`,ua:`Курка качаторе`};var g={en:`A classic dish from Italy, featuring chicken thigh, yellow onion, garlic, red bell pepper. A practical home-kitchen version with measured step ingredients and clear cooking methods.`,ua:`Класична страва з Італія. Основні складники: куряче стегно, жовта цибуля, часник, червоний солодкий перець. Домашній варіант із поетапними діями та точними кількостями продуктів.`};var c=[{en:`Pat the main ingredients dry. Brown in a hot heavy pan in batches for about 14 minutes, turning to color all sides.`,ua:`Обсушіть основні продукти. Обсмажуйте їх порціями на добре розігрітій важкій сковороді приблизно 14 хвилин, перевертаючи для рівної скоринки.`,t:[`searing`],m:14,i:[[`chicken-thigh`,800,`g`],[`extra-virgin-olive-oil`,45,`ml`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 9 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 9 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:9,i:[[`yellow-onion`,180,`g`],[`garlic`,4,`clove`],[`red-bell-pepper`,180,`g`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 50 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 50 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:50,i:[[`tomato-passata`,520,`g`],[`dry-white-wine`,160,`ml`],[`black-olives`,90,`g`],[`rosemary`,6,`g`],[`bay-leaf`,2,`leaf`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`parsley`,22,`g`],[`table-salt`,null,`to_taste`],[`ground-black-pepper`,null,`to_taste`]]}];var h={slug:t,id:n,country:`IT`,region:r,servings:4,minutes:76,title:l,text:g,steps:c};export{a as country,h as default,n as id,o as minutes,r as region,s as servings,t as slug,c as steps,g as text,l as title};